INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('d8cc53acbe4dc0b3', 'standard-fijian', 'word', 'ceguleka', 'ceguleka', 'punctuation mark', 'Comma (,); another Fijian name for this writing mark.', '', '', '', 'The school handout labels koma with ceguleka. Keep this punctuation sense separate from any unrelated sense of the same spelling.', '{"role":{"fijian":"","english":"separates parts of a sentence"},"relatedWords":["koma"],"comparison":"Ceguleka and koma can name the same mark. In another context, ceguleka can have a different meaning, so check what the writer is discussing.","searchKeywords":["comma","short pause","list separator"],"furtherLink":{"label":"Explore ceguleka in Ba Sangam Primary School · Year 4 punctuation","href":"https://sangamedu.ac.fj/wp-content/uploads/2021/07/Home-Study-Package-Year-4-22.pdf"},"quiz":true,"writingTerm":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"The school handout labels koma with ceguleka. Keep this punctuation sense separate from any unrelated sense of the same spelling."}}', '[{"sourceId":"2026-11-03-owner-writing-terms"},{"sourceId":"ba-sangam-fijian-year-4-punctuation"}]', '["writing-marks"]', 'ceguleka | comma (,); another fijian name for this writing mark. | | | comma | short pause | list separator', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
