INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('86c24a8e5ff70c5c', 'standard-fijian', 'word', 'simikoloni', 'simikoloni', 'punctuation mark', 'Semicolon (;)', '', '', '', 'The owner uses the USP spelling simikoloni. Other teaching material uses semikoloni; keep the two spellings searchable without silently replacing the supplied form.', '{"role":{"fijian":"","english":"divides closely related clauses or longer list items"},"relatedWords":["koma","digo","koloni"],"comparison":"A simikoloni is stronger than a koma but usually less final than a digo.","searchKeywords":["semicolon","semi colon","clause separator","semikoloni"],"furtherLink":{"label":"Explore simikoloni in Wilivola Vinaka · Fijian punctuation guide","href":"https://wol.jw.org/fj/wol/d/r169/lp-fn/1102001070"},"quiz":true,"writingTerm":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"The owner uses the USP spelling simikoloni. Other teaching material uses semikoloni; keep the two spellings searchable without silently replacing the supplied form."}}', '[{"sourceId":"2026-11-03-owner-writing-terms"},{"sourceId":"jw-fijian-punctuation-guide"},{"sourceId":"ba-sangam-fijian-year-4-punctuation"}]', '["writing-marks"]', 'simikoloni | semicolon (;) | | | semicolon | semi colon | clause separator | semikoloni', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
