INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('b0a8ca76e955260d', 'standard-fijian', 'word', 'komalili', 'komalili', 'punctuation mark', 'Single quotation marks (‘ ’) in the owner''s distinction.', '', '', '', 'The single-versus-double distinction follows the owner and school handout; another teaching guide uses komalili more broadly.', '{"role":{"fijian":"","english":"encloses quoted words"},"relatedWords":["kamalilirua"],"comparison":"Komalili is used for the single pair here; kamalilirua is the owner''s name for the double pair. Another teaching guide uses komalili for quotation marks more generally.","searchKeywords":["single quote","single quotation marks","apostrophe style"],"furtherLink":{"label":"Explore komalili in Wilivola Vinaka · Fijian punctuation guide","href":"https://wol.jw.org/fj/wol/d/r169/lp-fn/1102001070"},"quiz":true,"writingTerm":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"The single-versus-double distinction follows the owner and school handout; another teaching guide uses komalili more broadly."}}', '[{"sourceId":"2026-11-03-owner-writing-terms"},{"sourceId":"jw-fijian-punctuation-guide"},{"sourceId":"ba-sangam-fijian-year-4-punctuation"}]', '["writing-marks"]', 'komalili | single quotation marks (‘ ’) in the owner''s distinction. | | | single quote | single quotation marks | apostrophe style', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
