INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('4980cdb0694d11d9', 'standard-fijian', 'grammar-term', '-qu', 'qu', '', 'A suffix meaning ''my'' when attached directly to certain nouns, including body-part words.', '', 'In na batiqu, bati means teeth and -qu says they are mine. The suffix is attached to bati; it is not a separate word. In Vosa Vakaviti Raraba, a house is normally na noqu vale, not valequ. Possessive patterns can vary by dialect and by what is possessed.', '', 'The owner''s batiqu example and the school example attest this form. The direct versus noqu contrast is supported by the linguistic account. Check the role in any new phrase.', '{"usageExamples":[{"fijian":"na batiqu","english":"my teeth"}],"relatedWords":["bati","noqu","vale","ikurimuri"],"searchKeywords":["qu","my","possessive suffix","batiqu","body parts"],"grammarFunction":"A suffix meaning ''my'' when attached directly to certain nouns, including body-part words.","grammarExample":"na batiqu","furtherLink":{"label":"Explore -qu in QMUL GLOW 42: Fijian possessive classifiers as nominal Appl heads","href":"https://glowlinguistics.org/42/wp-content/uploads/sites/4/2019/03/GLOW_FJPoss.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"The owner''s batiqu example and the school example attest this form. The direct versus noqu contrast is supported by the linguistic account. Check the role in any new phrase."}}', '[{"sourceId":"owner-word-building-2026-11-03"},{"sourceId":"qmul-fijian-possession-2019"},{"sourceId":"fijian-school-batiqu"}]', '[]', '-qu | a suffix meaning ''my'' when attached directly to certain nouns, including body-part words. | | in na batiqu, bati means teeth and -qu says they are mine. the suffix is attached to bati; it is not a separate word. in vosa vakaviti raraba, a house is normally na noqu vale, not valequ. possessive patterns can vary by dialect and by what is possessed. | qu | my | possessive suffix | batiqu | body parts', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('a7e5db6688be3d68', 'standard-fijian', 'word', 'kete', 'kete', 'noun', 'The stomach or belly.', '', '', '', 'The cited Fijian passage has na ketequ. The English body-part gloss comes from the Fijian teaching list. Check the full phrase for a Tuvavosa role.', '{"usageExamples":[{"fijian":"na ketequ","english":"my stomach"}],"relatedWords":["-qu","bati","mata"],"searchKeywords":["stomach","belly","ketequ","body part"],"furtherLink":{"label":"Explore kete in FIJ101 Hand Book · Tikiniyago body-part list","href":"https://paperzz.com/doc/8937213/fij101-hand-book"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"The cited Fijian passage has na ketequ. The English body-part gloss comes from the Fijian teaching list. Check the full phrase for a Tuvavosa role."}}', '[{"sourceId":"fij101-handbook-body-parts"},{"sourceId":"fijian-jeremiah-ketequ"}]', '["body"]', 'kete | the stomach or belly. | | | stomach | belly | ketequ | body part', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('a1f5cbb8b02feaa4', 'standard-fijian', 'word', 'ilakolako', 'ilakolako', 'noun', 'A person''s manner of walking; how they walk.', '', '', '', 'Founder-supplied walking-manner sense. A full Fijian example and its phrase role still need checking. Keep the independently attested trip/journey sense separate.', '{"relatedWords":["lako","i-","drua"],"searchKeywords":["how someone walks","way of walking","walking style","gait"],"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Founder-supplied walking-manner sense. A full Fijian example and its phrase role still need checking. Keep the independently attested trip/journey sense separate."}}', '[{"sourceId":"naisema-founder-ilakolako-2026-11-05"}]', '["family"]', 'ilakolako | a person''s manner of walking; how they walk. | | | how someone walks | way of walking | walking style | gait', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('1cd0e5f0f990ff7b', 'standard-fijian', 'word', 'ilakolako', 'ilakolako', 'noun', 'A trip or journey.', '', '', '', 'Attested in an iTaukei Affairs Board report. The form invites comparison with lako, i- and repetition; the precise morphological analysis remains open to Tuvavosa review.', '{"usageExamples":[{"fijian":"e dua na ilakolako ni veisiko","english":"a journey to pay a visit"},{"fijian":"Na neitou ilakolako i Suva","english":"Our trip to Suva"}],"relatedWords":["lako","i-","drua"],"searchKeywords":["journey","trip","travel","visit"],"furtherLink":{"label":"Explore ilakolako in iTaukei Affairs Board Annual Report 2021–2022","href":"https://www.parliament.gov.fj/wp-content/uploads/2024/03/iTaukei-Affairs-Board-Annual-Report-2021%E2%80%932022.pdf"},"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Attested in an iTaukei Affairs Board report. The form invites comparison with lako, i- and repetition; the precise morphological analysis remains open to Tuvavosa review."}}', '[{"sourceId":"itaukei-affairs-ilakolako-2022"},{"sourceId":"naisema-founder-ilakolako-2026-11-05"}]', '["boats"]', 'ilakolako | a trip or journey. | | | journey | trip | travel | visit', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('1574ac41ec0a23a7', 'standard-fijian', 'word', 'sa', 'sa', 'grammar marker', 'Marks an event or state as now in effect or relevant in the situation being discussed. Its English rendering depends on context.', '', 'In Au sa lako, sa is a durugauna before the yavu lako. It draws attention to the going as now in effect or relevant. It is not simply an English past-tense marker; a context may favour ''I am going'' or ''I have gone''. Sa can also occur alongside future na in an appropriate context.', '', 'The owner supplied Au sa lako as an inquiry contrast with Au na lako. The English example represents a present-departure context, not an invariant translation. Check further contexts with fluent speakers.', '{"usageExamples":[{"fijian":"Au sa lako","english":"I am going / I am leaving now (in a present departure context)."}],"relatedWords":["na","lako","durugauna","matavu"],"searchKeywords":["now","already","current relevance","aspect","time","going","future contrast"],"grammarExample":"Au sa lako","furtherLink":{"label":"Explore sa in David G. Arms · Fijian sā and se Aspect","href":"https://openresearch-repository.anu.edu.au/server/api/core/bitstreams/ed84f88d-599f-4e6b-ad77-cda0bbf73c01/content"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"The owner supplied Au sa lako as an inquiry contrast with Au na lako. The English example represents a present-departure context, not an invariant translation. Check further contexts with fluent speakers."}}', '[{"sourceId":"anu-arms-sa-se-aspect"},{"sourceId":"534756bd7910"}]', '[]', 'sa | marks an event or state as now in effect or relevant in the situation being discussed. its english rendering depends on context. | | in au sa lako, sa is a durugauna before the yavu lako. it draws attention to the going as now in effect or relevant. it is not simply an english past-tense marker; a context may favour ''i am going'' or ''i have gone''. sa can also occur alongside future na in an appropriate context. | now | already | current relevance | aspect | time | going | future contrast', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('ef98ec75c0d28851', 'standard-fijian', 'word', 'na', 'na', 'grammar marker', 'Places the action or state ahead: in Au na lako, ''I will go''.', '', 'Here na follows au and precedes the yavu lako in a matavu. It marks future time. This is a different use from na at the start of a matanauni such as na vale.', '', 'The owner supplied Au na lako as the contrast with Au sa lako. Keep this future marker separate from nominal na.', '{"usageExamples":[{"fijian":"Au na lako","english":"I will go."}],"relatedWords":["sa","lako","durugauna","mata"],"searchKeywords":["will","future","time","going","sa contrast"],"grammarExample":"Au na lako","furtherLink":{"label":"Explore na in Pacific Languages: An Introduction · Fijian tense markers","href":"https://kir.oer4pacific.org/id/eprint/67/1/PacificLanguagesOA.pdf.pdf"},"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"The owner supplied Au na lako as the contrast with Au sa lako. Keep this future marker separate from nominal na."}}', '[{"sourceId":"pacific-languages-fijian-na-future"},{"sourceId":"anu-arms-sa-se-aspect"}]', '[]', 'na | places the action or state ahead: in au na lako, ''i will go''. | | here na follows au and precedes the yavu lako in a matavu. it marks future time. this is a different use from na at the start of a matanauni such as na vale. | will | future | time | going | sa contrast', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('94b8e6870680274c', 'standard-fijian', 'word', 'na', 'na', 'grammar marker', 'Opens a common noun phrase, as in na vale (''the house'').', '', 'In na vale, na is the mata and vale is the yavu of the matanauni. This na is not the future durugauna in Au na lako; its job depends on the whole phrase.', '', 'Distinct function of the same written form. The Tuvavosa visual guide treats na as mata in a nominal phrase. Phrase-specific role remains open to team review.', '{"usageExamples":[{"fijian":"na vale","english":"the house"}],"relatedWords":["sa","vale","mata","matanauni raraba"],"searchKeywords":["noun phrase","common noun","article","house","mata","future contrast"],"grammarExample":"na vale","appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Distinct function of the same written form. The Tuvavosa visual guide treats na as mata in a nominal phrase. Phrase-specific role remains open to team review."}}', '[{"sourceId":"534756bd7910"}]', '[]', 'na | opens a common noun phrase, as in na vale (''the house''). | | in na vale, na is the mata and vale is the yavu of the matanauni. this na is not the future durugauna in au na lako; its job depends on the whole phrase. | noun phrase | common noun | article | house | mata | future contrast', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
INSERT INTO `expression` (`id`, `variety`, `kind`, `headword`, `slug`, `part_of_speech`, `general_meaning`, `literal_meaning`, `grammar_note`, `pronunciation`, `notes`, `details`, `citations`, `themes`, `search_text`, `created_by`, `updated_by`, `updated_at`) VALUES ('e37f0a9bbd9867de', 'standard-fijian', 'word', 'auwa', 'auwa', 'noun', 'An hour; another spelling of aua.', '', '', '', 'Founder-supplied spelling. Aua is also recorded by an independent vocabulary; preferred spelling still needs checking.', '{"relatedWords":["aua","au","miniti"],"comparison":"Au is the pronoun I/me; auwa is a time word meaning an hour. Aua is another spelling of the time word.","searchKeywords":["hour","sixty minutes","time"],"quiz":true,"appsSite":{"englishChecked":true,"status":"needs review; meaning reviewed","notes":"Founder-supplied spelling. Aua is also recorded by an independent vocabulary; preferred spelling still needs checking."}}', '[{"sourceId":"naisema-founder-au-yau-aua-auwa-2026-11-03"}]', '["time"]', 'auwa | an hour; another spelling of aua. | | | hour | sixty minutes | time', 'apps.naisema.com', 'apps.naisema.com', 1794700800000);
--> statement-breakpoint
